<?php
namespace App\Controllers\Gestion;use App\Core\Controller;use App\Core\Request;use App\Core\Database;use App\Services\NotificationService;
class NotificacionController extends Controller{public function index(Request $r):void{$s=Database::connection()->prepare('SELECT n.*,tn.nombre AS tipo,cn.nombre AS canal FROM notificaciones n JOIN tipos_notificacion tn ON tn.id=n.tipo_notificacion_id JOIN canales_notificacion cn ON cn.id=n.canal_id WHERE n.entorno_id=:e OR n.entorno_id IS NULL ORDER BY n.created_at DESC LIMIT 300');$s->execute(['e'=>active_environment_id()]);$this->view('notificaciones/index',['title'=>'Notificaciones','notifications'=>$s->fetchAll()]);}public function process(Request $r):void{$result=(new NotificationService())->processBatch(50);\App\Core\Session::flash('success','Procesadas: '.json_encode($result));$this->redirect('/notificaciones');}}
